from collections import defaultdict


def dedupe_contacts(rows):
    """Collapse duplicate contact rows into one record per person.

    See the data team's rules for details. Rows that have neither a valid
    email nor a valid phone are dropped before matching.
    """

    # ---------- normalization helpers ----------

    def normalize_email(raw):
        email = (raw or "").strip().lower()
        if "@" not in email:
            return email
        local, _, domain = email.rpartition("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
        return local + "@" + domain

    def is_valid_email(email):
        if email.count("@") != 1:
            return False
        local, domain = email.split("@")
        if not local:
            return False
        return "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(raw):
        digits = "".join(ch for ch in (raw or "") if ch.isdigit())
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        return digits

    def is_valid_phone(phone):
        return len(phone) == 10

    # ---------- pre-process rows ----------

    records = []  # (original_index, row, norm_email_or_None, norm_phone_or_None)
    for idx, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))
        valid_email = email if is_valid_email(email) else None
        valid_phone = phone if is_valid_phone(phone) else None
        if valid_email is None and valid_phone is None:
            continue  # rule 4
        records.append((idx, row, valid_email, valid_phone))

    n = len(records)

    # ---------- union-find for transitive matching ----------

    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # keep the lower index as root so output ordering is easy
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email = {}
    by_phone_last = {}
    for pos, (idx, row, email, phone) in enumerate(records):
        if email is not None:
            if email in by_email:
                union(pos, by_email[email])
            else:
                by_email[email] = pos
        if phone is not None:
            last = (row.get("last_name") or "").strip().lower()
            if last:
                key = (phone, last)
                if key in by_phone_last:
                    union(pos, by_phone_last[key])
                else:
                    by_phone_last[key] = pos

    groups = defaultdict(list)
    for pos in range(n):
        groups[find(pos)].append(pos)

    # ---------- merge each group ----------

    def recency_key(rec):
        # most recent `updated` first; ties -> earlier input index first
        idx, row, _, _ = rec
        return (row["updated"], -idx)

    def pick_field(sorted_recs, field):
        for _, row, _, _ in sorted_recs:
            value = (row.get(field) or "").strip()
            if value:
                return value
        return ""

    def pick_email(sorted_recs):
        for _, _, email, _ in sorted_recs:
            if email is not None:
                return email
        return ""

    def pick_phone(sorted_recs):
        for _, _, _, phone in sorted_recs:
            if phone is not None:
                return phone
        return ""

    def merge_tags(recs):
        tags = set()
        for _, row, _, _ in recs:
            for tag in (row.get("tags") or "").split(";"):
                tag = tag.strip().lower()
                if tag:
                    tags.add(tag)
        return ";".join(sorted(tags))

    def merge_opted_out(recs):
        for _, row, _, _ in recs:
            if (row.get("opted_out") or "").strip().upper() == "Y":
                return "Y"
        return "N"

    output = []
    # rule 7: order people by their earliest row in the input
    for root in sorted(groups, key=lambda r: records[r][0]):
        recs = [records[p] for p in groups[root]]
        recs_by_recency = sorted(recs, key=recency_key, reverse=True)
        output.append({
            "first_name": pick_field(recs_by_recency, "first_name"),
            "last_name": pick_field(recs_by_recency, "last_name"),
            "email": pick_email(recs_by_recency),
            "phone": pick_phone(recs_by_recency),
            "zip": pick_field(recs_by_recency, "zip"),
            "tags": merge_tags(recs),
            "opted_out": merge_opted_out(recs),
            "updated": max(row["updated"] for _, row, _, _ in recs),
        })

    return output
```

A few notes on how this maps to the rules:

- **Rules 1–3** are the `normalize_*` / `is_valid_*` helpers. Gmail normalization strips the `+tag` before removing dots, and `googlemail.com` collapses to `gmail.com`.
- **Rule 4** drops rows before any matching happens, so an invalid row can't bridge two groups.
- **Rule 5** uses union-find so matching is transitive. Phone matching only applies when the stripped last name is non-empty.
- **Rule 6** sorts each group by `(updated desc, input index asc)` once, then picks the first non-empty value per field. ISO dates sort correctly as strings, so no parsing is needed. `opted_out` is "Y" if any row says Y (case-insensitive), so an opt-out on an old duplicate still wins.
- **Rule 7** orders groups by the lowest original row index in each group.

One thing worth doing before you send tomorrow: filter the result to `opted_out == "N"` and run a quick count of how many rows collapsed, so you can sanity-check the dedupe against your CRM's own numbers.
